-- 001115_update_cookies_page.down.sql
-- Restores the cookies page blocks exactly as seeded by
-- 000885_site_pages.up.sql (the pre-§19-consent-model version).

BEGIN;

UPDATE pages SET
    blocks = '[{"id": "cookies-h", "type": "heading", "visible": true, "props": {"text": "Cookie Policy", "level": "h1", "size": "2xl", "align": "center", "eyebrow": "Legal", "subheading": "Last updated: October 18, 2026 · A short list, because we use few cookies."}}, {"id": "cookies-media", "type": "media", "visible": true, "props": {"media": {"media_id": "", "url": "/illustrations/cookies.svg", "alt": "Illustration of a cookie with a settings gear"}, "layout": "contained", "lightbox": false}}, {"id": "cookies-intro", "type": "content", "visible": true, "props": {"html": "\n<p>Cookies are small text files a site stores on your device. Japa.to uses a deliberately small set — enough to keep you signed in, keep the site secure, and remember your preferences. We do not use advertising trackers or third-party profiling cookies.</p>\n<h2>Cookies we set</h2>\n", "prose_style": "article"}}, {"id": "cookies-table", "type": "table", "visible": true, "props": {"columns": [{"key": "name", "label": "Cookie"}, {"key": "category", "label": "Category"}, {"key": "purpose", "label": "Purpose"}, {"key": "duration", "label": "Duration"}], "rows": [{"name": "jc_token", "category": "Strictly necessary", "purpose": "Your signed-in session", "duration": "Short-lived; renewed automatically"}, {"name": "jc_refresh", "category": "Strictly necessary", "purpose": "Securely refreshes your session", "duration": "Up to 30 days"}, {"name": "csrf_token", "category": "Strictly necessary", "purpose": "Protects actions from cross-site forgery", "duration": "Session"}, {"name": "jc_theme", "category": "Preferences", "purpose": "Remembers light/dark/system appearance", "duration": "1 year"}, {"name": "jc_locale", "category": "Preferences", "purpose": "Remembers your language", "duration": "1 year"}, {"name": "nav_pin_override", "category": "Preferences", "purpose": "Remembers your nav rail preference", "duration": "1 year"}, {"name": "jc_journey_token", "category": "Preferences", "purpose": "Keeps guest checklist/assessment progress", "duration": "90 days"}], "sortable": false, "striped": true}}, {"id": "cookies-body", "type": "content", "visible": true, "props": {"html": "\n<h2>Categories explained</h2>\n<ul>\n  <li><strong>Strictly necessary</strong> — the Service cannot work without these. They cannot be switched off.</li>\n  <li><strong>Preferences</strong> — remember choices like theme and language. The site still works without them; it just won''t remember you.</li>\n  <li><strong>Analytics</strong> — we use privacy-friendly, aggregate analytics to understand which features help people. Where analytics run, they do not use cross-site tracking cookies or build individual advertising profiles.</li>\n</ul>\n<h2>What we do not use</h2>\n<ul>\n  <li>No third-party advertising or retargeting cookies.</li>\n  <li>No social-media tracking pixels.</li>\n  <li>No sale of cookie-derived data to brokers.</li>\n</ul>\n<h2>Managing cookies</h2>\n<p>You can block or delete cookies in your browser settings at any time. Blocking strictly-necessary cookies will sign you out and parts of the site will stop working — for obvious reasons, a session cookie is required to stay signed in.</p>\n<p>Browser-level \"Do Not Track\" signals are respected for analytics where the browser sends one.</p>\n<h2>Changes</h2>\n<p>If we add a new cookie category we will update this page and, where required, ask for consent first. Questions: <a href=\"/contact\">contact us</a> or see the <a href=\"/privacy\">Privacy Policy</a>.</p>\n", "prose_style": "article"}}, {"id": "cookies-cta", "type": "cta_banner", "visible": true, "props": {"headline": "Prefer fewer cookies?", "subhead": "Your privacy controls — data export, deletion and more — live in Settings.", "ctas": [{"label": "Open Settings", "href": "/settings", "variant": "primary"}, {"label": "Privacy Policy", "href": "/privacy", "variant": "ghost"}], "alignment": "center"}}]'::jsonb,
    meta = jsonb_set(meta, '{description}', '"Which cookies Japa.to sets, what each does, and how to manage or block them."'::jsonb),
    updated_at = now()
WHERE slug = 'cookies'
  AND page_type = 'page'
  AND status = 'published';

COMMIT;
